                    },
                    {
                      "name": "3. Billing System Integration",
                      "subtitle": "Connect Stripe webhooks for automated monthly subscription renewal.",
                      "icon": "💳",
                      "status": "Active",
                      "meta": "Priority: High"
                    },
                    {
                      "name": "4. Frontend Component Audit",
                      "subtitle": "Review reusable UI components for WCAG 2.1 accessibility compliance.",
                      "icon": "🎨",
                      "status": "Pending",
                      "meta": "Priority: Medium"
                    },
                    {
                      "name": "5. User Onboarding Flow",
                      "subtitle": "Design and build a 3-step interactive product walkthrough tour.",
                      "icon": "🚀",
